ValidationRule.errorConditionFormula:
OR( AND( ISPICKVAL(PRIORVALUE( Status ), 'Cerrada Ganada'), NOT(ISPICKVAL(Status, 'Cerrada Ganada')), OR(RecordType.DeveloperName = 'Planes_Beneficio_Fiscal_Prospecto', RecordType.DeveloperName = 'Casa_de_Bolsa_Prospecto', RecordType.DeveloperName = 'Prospecto', RecordType.DeveloperName = 'Seguros_Prospecto'), NOT($Permission.bypassValidationRules)),
AND( ISPICKVAL(PRIORVALUE(Status), 'Cerrada Perdida'), NOT(ISPICKVAL(Status, 'Cerrada Perdida')), OR(RecordType.DeveloperName = 'Planes_Beneficio_Fiscal_Prospecto', RecordType.DeveloperName = 'Casa_de_Bolsa_Prospecto', RecordType.DeveloperName = 'Prospecto', RecordType.DeveloperName = 'Seguros_Prospecto'), NOT($Permission.bypassValidationRules))
)
